/* JS Learning · CISA Certification Hub
   Module is loaded on demand by index.html. Curriculum and question banks live in separate JSON files.
   All user work is saved through the parent application's existing authenticated Firebase progress document.
*/
let root, readParent, writeParent, syllabus, templates={}, state, tab='overview', weekIndex=0, focusedTopic=null, editTopic=null;
let examBank=null, examPage=0, reviewQuestion=0, timer=null, stopWatch=null, stopwatchStart=null, stopwatchElapsed=0;
const WD=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const $=(sel)=>root?.querySelector(sel);
const $$=(sel)=>[...(root?.querySelectorAll(sel)||[])];
const h=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmtDate=ds=>ds?new Date(ds+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const asDate=s=>new Date(s+'T12:00:00');
const dateStr=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const dateAdd=(s,n)=>{const d=asDate(s);d.setDate(d.getDate()+n);return dateStr(d)};
const dayDiff=(a,b)=>Math.round((asDate(b)-asDate(a))/86400000);
const dayIdx=d=>(asDate(d).getDay()+6)%7;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const pad=n=>String(n).padStart(2,'0');
const simple=xs=>xs.filter(Boolean).join(' · ');
function defaultState(){return {planMode:'normal',plans:{},complete:{},topicEdits:{},order:[],customTasks:[],hidden:[],logs:[],notes:{},revisions:{},results:[],drafts:{},activeMock:null,registration:{registered:false,booked:false},revisionCounts:{},updatedAt:Date.now()};}
function persist(){state.updatedAt=Date.now();writeParent(state);}
async function fetchData(file){const r=await fetch(new URL(file,import.meta.url),{cache:'no-store'});if(!r.ok)throw Error('Unable to load '+file+' ('+r.status+'). Upload the entire cisa/ directory.');return r.json()}
function allOfficial(){return syllabus.domains.flatMap(d=>d.topics)}
function allTopics(){const base=allOfficial(),custom=state.customTasks||[];const ids=state.order||[];const position=new Map(ids.map((id,i)=>[id,i]));return base.concat(custom).sort((a,b)=>(position.get(a.id)??9999)-(position.get(b.id)??9999))}
function titleOf(t){return state.topicEdits?.[t.id]?.title||t.title}
function minsOf(t){return clamp(Number(state.topicEdits?.[t.id]?.minutes??t.minutes??70)||70,15,300)}
function noteOf(t){return state.topicEdits?.[t.id]?.notes||''}
function includedTopics(){return allTopics().filter(t=>!state.hidden.includes(t.id))}
function getPlan(){return state.plans[state.planMode]||templates[state.planMode]}
function ensureState(){state=Object.assign(defaultState(),readParent()||{});state.plans=state.plans||{};state.complete=state.complete||{};state.topicEdits=state.topicEdits||{};state.order=state.order||[];state.customTasks=state.customTasks||[];state.hidden=state.hidden||[];state.logs=state.logs||[];state.notes=state.notes||{};state.revisions=state.revisions||{};state.results=state.results||[];state.drafts=state.drafts||{};state.registration=state.registration||{registered:false,booked:false};state.revisionCounts=state.revisionCounts||{}; if(!state.plans.normal)state.plans.normal=structuredClone(templates.normal);if(!state.plans.relaxed)state.plans.relaxed=structuredClone(templates.relaxed);if(!templates[state.planMode])state.planMode='normal';}
function totalComplete(){const done=allOfficial().filter(t=>state.complete[t.id]);return {done:done.length,total:allOfficial().length,percent:pct(done.length,allOfficial().length)}}
function timeline(){const p=getPlan(),result=[],byday={},tasks=includedTopics(),review=Math.max(3,Number(p.reviewDays)||10);if(!p.start||!p.examDate||dayDiff(p.start,p.examDate)<3)return {byday,days:[],warning:'Study start must be at least three days before the target exam date.'};
 const studyEnd=dateAdd(p.examDate,-review); const capacity={}, dates=[];
 for(let ds=p.start; ds<=studyEnd && dates.length<730;ds=dateAdd(ds,1)){
   const min=clamp(Number((p.weeklyMinutes||[])[dayIdx(ds)])||0,0,600);if(min>0){capacity[ds]=min;dates.push(ds)}
 }
 let cursor=0,overflow=0;
 for(const t of tasks){let left=minsOf(t),part=0,override=(state.topicEdits[t.id]||{}).date; if(override){(byday[override]??=[]).push({topic:t,minutes:left,customDate:true,part:1});continue}
  while(left>0){if(cursor>=dates.length){overflow+=left;break} const ds=dates[cursor],used=Math.min(left,capacity[ds]); if(used>0){(byday[ds]??=[]).push({topic:t,minutes:used,part:++part});left-=used;capacity[ds]-=used}if(capacity[ds]<1)cursor++}
 }
 // Exams are deliberately in the final revision period. Mock bookings are suggestions, not PSI appointments.
 for(const [id,offset] of [[1,review-1],[2,Math.max(4,Math.floor(review/2))],[3,2]]){const ds=dateAdd(p.examDate,-offset);(byday[ds]??=[]).push({mock:id,minutes:240})}
 (byday[p.examDate]??=[]).push({exam:true,minutes:240});
 const days=Object.keys(byday).sort();let warning='';if(overflow)warning=`Your study schedule is short by ${Math.ceil(overflow/60)} hours. Increase study minutes, extend dates, or reduce optional tasks.`;if(tasks.length<60)warning+=(warning?' ':'')+'Some official syllabus topics are excluded; coverage will be incomplete.';
 return {byday,days,warning,overflow,studyEnd};}
function domainScore(){const data=syllabus.domains.map(d=>({domain:d.id,weight:d.weight,name:d.name,questions:0,correct:0,completed:d.topics.filter(t=>state.complete[t.id]).length,total:d.topics.length,confidence:[]}));const byId=new Map(data.map(d=>[d.domain,d]));for(const r of state.results){const latest=r.stats||{};for(const [k,v] of Object.entries(latest)){const d=byId.get(Number(k));if(d){d.questions+=Number(v.total)||0;d.correct+=Number(v.correct)||0}}}for(const log of state.logs){const d=byId.get(Number(log.domain));if(d&&Number(log.questions)>0){d.questions+=Number(log.questions);d.correct+=Number(log.correct)||0}if(d&&Number(log.confidence)>0)d.confidence.push(+log.confidence)}return data.map(d=>({...d,accuracy:d.questions?pct(d.correct,d.questions):null,coverage:pct(d.completed,d.total),confidence:d.confidence.length?+(d.confidence.reduce((a,b)=>a+b,0)/d.confidence.length).toFixed(1):null}))}
function weakTopics(){const m=new Map();for(const r of state.results){const entries=r.topicStats||{};for(const [id,v] of Object.entries(entries)){const old=m.get(id)||{correct:0,total:0};old.correct+=v.correct;old.total+=v.total;m.set(id,old)}}for(const log of state.logs){if(!log.topicId||!+log.questions)continue;const old=m.get(log.topicId)||{correct:0,total:0};old.correct+=Number(log.correct)||0;old.total+=Number(log.questions)||0;m.set(log.topicId,old)}return allTopics().map(t=>{const a=m.get(t.id)||{correct:0,total:0},accuracy=a.total?pct(a.correct,a.total):null,weight=syllabus.domains.find(d=>d.id===t.domain)?.weight||10;const points=a.total?clamp(80-accuracy,0,80)*(Math.min(a.total,20)/20):0;const priority=points+weight*.45+(!state.complete[t.id]?16:0);return {topic:t,correct:a.correct,total:a.total,accuracy,priority,done:!!state.complete[t.id]}}).sort((a,b)=>b.priority-a.priority)}
function button(act,label,kind='',extra=''){return `<button type="button" class="cisa-btn ${kind}" data-action="${act}" ${extra}>${label}</button>`}
function badge(text,type=''){return `<span class="cisa-badge ${type}">${h(text)}</span>`}
function progress(value){return `<span class="cisa-progress"><i style="width:${clamp(value,0,100)}%"></i></span>`}
function kpi(label,value,sub){return `<div class="cisa-kpi"><span>${h(label)}</span><strong>${h(value)}</strong><small>${h(sub)}</small></div>`}
function header(){const p=getPlan();return `<div class="cisa-hero"><div><div class="cisa-kicker">JS LEARNING / CERTIFICATION TRACK</div><h1>CISA Study Hub</h1><p>A personal audit-certification workspace: study the five domains, customize every date and task, record work, revise weak areas, and sit three full-length practice exams.</p></div><div class="cisa-hero-chip"><small>Exam target</small><strong>${h(fmtDate(p.examDate))}</strong><small>${h(state.planMode==='normal'?'Normal plan':'Relaxed plan')}</small></div></div><div class="cisa-tabs" role="navigation" aria-label="CISA sections">${[['overview','Overview'],['planner','Study planner'],['syllabus','Course & syllabus'],['recorder','Daily recorder'],['revision','Revision'],['mocks','Mock exams'],['analytics','Analytics'],['notes','Notes & backup']].map(([k,v])=>`<button type="button" data-action="nav" data-target="${k}" aria-current="${tab===k}">${v}</button>`).join('')}</div>`}
function overview(){const c=totalComplete(),scores=domainScore(),p=getPlan(),t=timeline(),recent=state.results.at(-1),mins=state.logs.reduce((n,l)=>n+(Number(l.minutes)||0),0),next=t.days.filter(d=>d>=dateStr(new Date())).slice(0,3);
 return `<div class="cisa-grid">${kpi('Official topics completed',`${c.done} / ${c.total}`,`${c.percent}% syllabus coverage`)}${kpi('Study hours logged',(mins/60).toFixed(1)+'h',`${state.logs.length} recorded sessions`)}${kpi('Mock exams submitted',state.results.length,'3 original full-length sets')}${kpi('Latest mock',recent?pct(recent.correct,recent.total)+'%':'Not taken',recent?fmtDate(recent.date.slice(0,10)):'No results yet')}</div><div class="cisa-section cisa-grid two"><section class="cisa-card"><div class="cisa-row top"><div><div class="cisa-overline">Your route</div><h2>${h(p.title)}</h2></div>${badge(state.planMode==='normal'?'Accelerated':'Flexible')}</div>${progress(c.percent)}<p class="cisa-text cisa-muted">${h(p.description)}</p><div class="cisa-steps"><div class="cisa-step"><b>November</b>Auditing & governance</div><div class="cisa-step"><b>December</b>Build deeper domain knowledge</div><div class="cisa-step"><b>January</b>Mocks, revision & exam</div></div><div class="cisa-actions">${button('mode-normal','Normal plan',state.planMode==='normal'?'primary':'')}${button('mode-relaxed','Relaxed plan',state.planMode==='relaxed'?'primary':'')}${button('nav','Customize schedule →','','data-target="planner"')}</div></section><section class="cisa-card"><div class="cisa-row"><h2>Readiness by domain</h2>${badge('Weighted 18 / 18 / 12 / 26 / 26')}</div>${scores.map(d=>`<div class="cisa-domain"><div class="cisa-row"><strong>D${d.domain} · ${h(d.name)}</strong><span class="cisa-mini">${d.coverage}% studied · ${d.accuracy===null?'No practice':d.accuracy+'% practice'}</span></div>${progress(d.coverage)}</div>`).join('')}</section></div><div class="cisa-section cisa-grid two"><section class="cisa-card"><h2>Next scheduled activities</h2>${next.length?next.map(ds=>`<div class="cisa-domain"><div class="cisa-row"><b>${h(fmtDate(ds))}</b>${badge(t.byday[ds].length+' item(s)')}</div><p class="cisa-mini">${h(t.byday[ds].slice(0,2).map(x=>x.topic?titleOf(x.topic):x.mock?'Mock exam '+x.mock:'CISA examination').join(' · '))}</p></div>`).join(''):'<div class="cisa-empty">No future assignments in this plan. Customize the dates or view your completed work.</div>'}<div class="cisa-actions">${button('nav','View planner →','primary','data-target="planner"')}</div></section><section class="cisa-card"><h2>Revision focus</h2>${weakTopics().slice(0,4).map(x=>`<div class="cisa-domain"><div class="cisa-row"><strong>${h(x.topic.id)} · ${h(titleOf(x.topic))}</strong>${badge(x.accuracy===null?'Not assessed':x.accuracy+'% accuracy',x.accuracy!==null&&x.accuracy<70?'warn':'')}</div><span class="cisa-mini">${x.done?'Covered previously':'Still to study'} · ${x.total} tracked questions</span></div>`).join('')}<div class="cisa-actions">${button('nav','Open revision center →','','data-target="revision"')}</div></section></div><div class="cisa-callout">The practice results are learning indicators, not an ISACA scaled score. Verify your official PSI booking separately; entering a target date here does not book an exam.</div>`}
function weeklyFields(p){return `<div class="cisa-week">${WD.map((d,i)=>`<label>${d}<input name="wd${i}" type="number" min="0" max="600" step="15" value="${+p.weeklyMinutes[i]||0}" aria-label="${d} study minutes"></label>`).join('')}</div>`}
function planner(){const p=getPlan(),t=timeline(),now=dateStr(new Date()),days=t.days,perWeek=7,maxWeek=Math.max(0,Math.ceil((dayDiff(p.start,p.examDate)+1)/7)-1);weekIndex=clamp(weekIndex,0,maxWeek);const wkStart=dateAdd(p.start,weekIndex*7),wkEnd=dateAdd(wkStart,6),visible=Array.from({length:7},(_,i)=>dateAdd(wkStart,i)).filter(x=>x<=p.examDate);const capacity=(p.weeklyMinutes||[]).reduce((n,v)=>n+Number(v||0),0); const overdueMap=new Map(); for(const ds of days.filter(d=>d<now)){for(const it of t.byday[ds]){if(it.topic&&!state.complete[it.topic.id])overdueMap.set(it.topic.id,it.topic)}}const overdue=[...overdueMap.values()];
 return `<div class="cisa-grid two cisa-section"><section class="cisa-card"><div class="cisa-row"><div><div class="cisa-overline">Edit your own plan</div><h2>Plan settings</h2></div>${badge(state.planMode==='normal'?'Normal':'Relaxed')}</div><div class="cisa-actions" style="margin-bottom:16px">${button('mode-normal','Normal',state.planMode==='normal'?'primary':'')}${button('mode-relaxed','Relaxed',state.planMode==='relaxed'?'primary':'')}</div><form data-form="plan"><div class="cisa-fields"><label>Study start<input type="date" name="start" required value="${h(p.start)}"></label><label>Target exam date<input type="date" name="examDate" required value="${h(p.examDate)}"></label><label>Deadline<input type="date" name="deadline" required value="${h(p.deadline)}"></label><label>Final revision days<input type="number" name="reviewDays" min="3" max="40" required value="${+p.reviewDays}"></label><label class="cisa-field-wide">Plan name<input name="title" maxlength="90" value="${h(p.title)}"></label></div><div class="cisa-divider"></div><b style="font-size:12px">Daily study budget (minutes; use 0 for a rest day)</b>${weeklyFields(p)}<div class="cisa-actions" style="margin-top:15px"><button class="cisa-btn primary" type="submit">Save & recalculate schedule</button>${button('reset-plan','Restore default plan')}</div></form><div class="cisa-help" style="margin-top:14px">Total ${Math.round(capacity/60*10)/10} hours per week. Changing dates or daily minutes recalculates unfinished assignments; completed topics, journal entries, results, and custom tasks are preserved.</div></section><section class="cisa-card"><div class="cisa-overline">Your planner</div><h2>Week ${weekIndex+1} · ${h(fmtDate(wkStart))}–${h(fmtDate(wkEnd))}</h2><div class="cisa-actions" style="margin-bottom:14px">${button('prev-week','← Previous','',''+(weekIndex===0?'disabled':''))}${button('today-week','Current week')}${button('next-week','Next →','',weekIndex>=maxWeek?'disabled':'')}</div>${t.warning?`<div class="cisa-callout">${h(t.warning)}</div>`:''}${overdue.length?`<div class="cisa-callout" style="margin-top:10px"><strong>${overdue.length} unfinished topics from earlier dates</strong><div class="cisa-mini">${overdue.slice(0,5).map(x=>`<div class="cisa-row" style="margin-top:7px"><span>${h(x.id)} · ${h(titleOf(x))}</span>${button('catchup','Move to next study day','sm',`data-topic="${h(x.id)}"`)}</div>`).join('')}</div></div>`:''}<div class="cisa-scroll" style="margin-top:12px">${visible.length?visible.map(ds=>`<div class="cisa-day ${ds===now?'today':''}"><div class="cisa-row"><h3>${h(fmtDate(ds))}</h3>${ds===now?badge('Today'):''}</div>${(t.byday[ds]||[]).map(e=>e.topic?`<div class="cisa-task ${state.complete[e.topic.id]?'done':''}"><label class="cisa-check"><input type="checkbox" data-action="complete" data-topic="${h(e.topic.id)}" ${state.complete[e.topic.id]?'checked':''}><span><strong>${h(e.topic.id)} · ${h(titleOf(e.topic))}</strong><small>${e.minutes} min${e.part>1?' · Part '+e.part:''} · ${h(e.topic.section||'Custom')}</small></span></label><div class="cisa-task-actions">${button('open-topic','Read','sm',`data-topic="${h(e.topic.id)}"`)}${button('edit-topic','Edit','sm',`data-topic="${h(e.topic.id)}"`)}</div></div>`:`<div class="cisa-task"><span style="font-size:12px"><strong>${e.mock?'Practice mock examination '+e.mock:'Target CISA exam'}</strong><small>${e.minutes} min · ${e.mock?'Use mock center':'External appointment required'}</small></span>${e.mock?button('nav','Mocks →','sm','data-target="mocks"'):''}</div>`).join('')}</div>`).join(''):'<div class="cisa-empty">No scheduled items this week. You can change the study days or advance to another week.</div>'}</div></section></div><div class="cisa-section cisa-card"><div class="cisa-row wrap"><div><h2>Customize topics & contents</h2><p class="cisa-mini">Rename topics, add personal chapters, change planned dates, adjust duration, reorder tasks or exclude optional work. Official syllabus coverage warns about excluded topics.</p></div>${button('new-topic','+ Add custom topic','primary')}</div>${editTopic?editTopicForm():''}<div class="cisa-table-wrap"><table class="cisa-table"><thead><tr><th>Topic</th><th>Domain</th><th>Time</th><th>Included</th><th>Actions</th></tr></thead><tbody>${allTopics().map((t,i)=>`<tr><td><strong>${h(t.id)} ${h(titleOf(t))}</strong>${noteOf(t)?`<div class="cisa-mini">${h(noteOf(t))}</div>`:''}</td><td>D${h(t.domain||'Custom')}</td><td>${minsOf(t)}m</td><td><label class="cisa-check"><input type="checkbox" data-action="include" data-topic="${h(t.id)}" ${state.hidden.includes(t.id)?'':'checked'}><span>${state.hidden.includes(t.id)?'Excluded':'Yes'}</span></label></td><td><div class="cisa-actions">${button('move-up','↑','sm',`data-topic="${h(t.id)}"`)}${button('move-down','↓','sm',`data-topic="${h(t.id)}"`)}${button('edit-topic','Edit','sm',`data-topic="${h(t.id)}"`)}${t.custom?button('delete-custom','Delete','danger sm',`data-topic="${h(t.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div></div>`}
function editTopicForm(){const t=allTopics().find(t=>t.id===editTopic)||{id:'new',title:'',minutes:60,domain:1,custom:true};const over=state.topicEdits[t.id]||{};const p=getPlan();return `<div class="cisa-edit"><div class="cisa-row"><h3>${editTopic==='new'?'Add personal study item':'Edit '+h(editTopic)}</h3>${button('cancel-edit','Close')}</div><form data-form="topic"><input type="hidden" name="id" value="${h(editTopic)}"><div class="cisa-fields four"><label class="cisa-field-wide">Content or topic title<input name="title" required maxlength="160" value="${h(titleOf(t))}"></label><label>Domain<select name="domain">${[1,2,3,4,5].map(n=>`<option value="${n}" ${t.domain===n?'selected':''}>Domain ${n}</option>`).join('')}</select></label><label>Minutes<input type="number" name="minutes" min="15" max="300" value="${minsOf(t)}"></label><label>Preferred date (optional)<input type="date" name="date" value="${h(over.date||'')}"></label><label class="cisa-field-wide">Your notes and learning objectives<textarea name="notes" maxlength="1500">${h(noteOf(t))}</textarea></label></div><div class="cisa-actions"><button type="submit" class="cisa-btn primary">Save topic changes</button>${button('cancel-edit','Cancel')}</div></form></div>`}
function syllabusUI(){const c=totalComplete();return `<section class="cisa-card cisa-section"><div class="cisa-row wrap"><div><h2>Official CISA topic map</h2><p class="cisa-text cisa-muted">60 published topics across five domains. Each topic has a concise original explanation, audit scenario, likely risk, suggested control and relevant evidence. Supplement these outlines with ISACA's study materials.</p></div>${badge(c.done+' / '+c.total+' completed')}</div>${progress(c.percent)}${focusedTopic?detailUI():''}${syllabus.domains.map(d=>`<div class="cisa-domain"><div class="cisa-row"><h3>Domain ${d.id}: ${h(d.name)}</h3>${badge(d.weight+'% exam weight')}</div>${d.topics.map(t=>`<div class="cisa-task ${state.complete[t.id]?'done':''}"><label class="cisa-check"><input type="checkbox" data-action="complete" data-topic="${h(t.id)}" ${state.complete[t.id]?'checked':''}><span><strong>${h(t.id)} · ${h(titleOf(t))}</strong><small>${h(t.section)} · ${minsOf(t)} minutes${state.hidden.includes(t.id)?' · Excluded from plan':''}</small></span></label><div class="cisa-task-actions">${button('open-topic','Open lesson','sm',`data-topic="${h(t.id)}"`)}</div></div>`).join('')}</div>`).join('')}</section>`}
function detailUI(){const t=allTopics().find(x=>x.id===focusedTopic);if(!t)return '';return `<section class="cisa-highlight" id="cisa-topic-detail"><div class="cisa-row wrap"><div><span class="cisa-overline">Domain ${h(t.domain)} · ${h(t.id)}</span><h2>${h(titleOf(t))}</h2></div>${button('close-topic','Close topic')}</div><p class="cisa-text">${h(t.intro||'Personal learning item. Use the notes and study recorder to capture how this fits your exam plan.')}</p><h3>Practical scenario</h3><p class="cisa-text">${h(t.example||noteOf(t)||'Set a practical learning objective for this study item.')}</p><h3>What the auditor should consider</h3><p class="cisa-text">${h(t.auditApproach||'Document the control objective, evidence, risk and relevant audit criteria.')}</p>${noteOf(t)?`<div class="cisa-help"><b>Personal learning notes:</b> ${h(noteOf(t))}</div>`:''}<div class="cisa-actions">${button('complete-toggle',state.complete[t.id]?'Mark not yet complete':'Mark topic complete','primary',`data-topic="${h(t.id)}"`)}${button('edit-topic','Customize this topic','','data-topic="'+h(t.id)+'"')}</div></section>`}
function recorder(){const today=dateStr(new Date()),sum=state.logs.reduce((n,x)=>n+Number(x.minutes||0),0);return `<div class="cisa-grid two cisa-section"><section class="cisa-card"><h2>Record a study session</h2><p class="cisa-text cisa-muted">Track actual learning, not just checkboxes. Use practice results and confidence to build targeted revision.</p><form data-form="log"><div class="cisa-fields"><label>Date<input type="date" name="date" value="${h(today)}" required></label><label>Duration (minutes)<input type="number" min="1" max="1440" name="minutes" required value="60" id="cisa-duration"></label><label>Domain<select name="domain">${syllabus.domains.map(d=>`<option value="${d.id}">D${d.id} · ${h(d.name)}</option>`).join('')}</select></label><label class="cisa-field-wide">Topic<select name="topicId"><option value="">General study / multiple topics</option>${allTopics().map(t=>`<option value="${h(t.id)}">${h(t.id)} · ${h(titleOf(t))}</option>`).join('')}</select></label><label>Questions attempted<input type="number" name="questions" min="0" max="1000" value="0"></label><label>Correct answers<input type="number" name="correct" min="0" max="1000" value="0"></label><label>Confidence (1–5)<select name="confidence">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n} / 5</option>`).join('')}</select></label><label class="cisa-field-wide">Learning notes / questions to revisit<textarea name="notes" maxlength="1000" placeholder="What did you learn? Which concepts are unclear?"></textarea></label></div><div class="cisa-actions" style="margin-top:15px"><button type="submit" class="cisa-btn primary">Save study record</button>${button('timer-start','Start timer')}${button('timer-stop','Stop timer') }<span class="cisa-timer" id="cisa-study-timer">00:00</span></div></form></section><section class="cisa-card"><h2>Session history</h2><p class="cisa-mini">${state.logs.length} sessions · ${(sum/60).toFixed(1)} hours logged</p><div class="cisa-scroll">${state.logs.length?[...state.logs].reverse().map(l=>`<div class="cisa-list-item"><div class="cisa-row"><strong>${h(fmtDate(l.date))}</strong>${badge(l.minutes+' min')}</div><div class="cisa-mini">D${h(l.domain)} ${h(l.topicId||'Mixed topics')} · ${l.questions?`${l.correct}/${l.questions} questions correct`:'Reading session'} · Confidence ${h(l.confidence)}/5</div>${l.notes?`<p class="cisa-text" style="margin:8px 0 0">${h(l.notes)}</p>`:''}<div class="cisa-actions">${button('delete-log','Delete','danger sm',`data-id="${h(l.id)}"`)}</div></div>`).join(''):'<div class="cisa-empty">No study sessions recorded yet.</div>'}</div></section></div>`}
function revisionsUI(){const rank=weakTopics(),scores=domainScore();const tracked=rank.filter(x=>x.total>0),incomplete=rank.filter(x=>!x.done),top=tracked.filter(x=>x.accuracy<80).slice(0,12);return `<div class="cisa-section cisa-grid two"><section class="cisa-card"><h2>Focus first: weakest domains</h2>${[...scores].sort((a,b)=>((a.accuracy??50)-(b.accuracy??50))||b.weight-a.weight).map(d=>`<div class="cisa-domain"><div class="cisa-row"><strong>D${d.domain} · ${h(d.name)}</strong>${badge(d.accuracy===null?'No data':d.accuracy+'%',d.accuracy!==null&&d.accuracy<75?'warn':'')}</div>${progress(d.accuracy??0)}<span class="cisa-mini">${d.questions} practice questions · ${d.coverage}% syllabus covered · ${d.weight}% exam weight</span></div>`).join('')}<div class="cisa-help">Priorities reflect practice accuracy, study coverage and exam weight. Small samples are treated cautiously; this is not a pass prediction.</div></section><section class="cisa-card"><h2>Recommended revision</h2>${(top.length?top:incomplete.slice(0,8)).map(x=>`<div class="cisa-domain"><div class="cisa-row wrap"><strong>${h(x.topic.id)} · ${h(titleOf(x.topic))}</strong>${badge(x.accuracy===null?'Not studied':x.accuracy+'% accuracy',x.accuracy!==null&&x.accuracy<70?'warn':'')}</div><p class="cisa-mini">${x.accuracy===null?'First understand the fundamentals and work through the example.':x.accuracy<60?'High-priority: re-read the topic, write a risk/control/evidence comparison and retry practice questions.':'Review key decision criteria, then practice applied audit scenarios.'}</p><div class="cisa-actions">${button('open-topic','Read chapter','sm',`data-topic="${h(x.topic.id)}"`)}${button('schedule-review','Add revision reminder','sm',`data-topic="${h(x.topic.id)}"`)}</div></div>`).join('')}${!top.length&&!incomplete.length?'<div class="cisa-empty">All topics marked covered. Use the mock exams to identify new revision priorities.</div>':''}</section></div>${focusedTopic?`<section class="cisa-card cisa-section">${detailUI()}</section>`:''}<section class="cisa-card cisa-section"><h2>Spaced revision reminders</h2><p class="cisa-mini">After a review, schedule the next check in 1, 3, 7 or 14 days depending on confidence. You can reschedule individually.</p>${Object.entries(state.revisions).length?Object.entries(state.revisions).sort((a,b)=>a[1].localeCompare(b[1])).map(([id,date])=>`<div class="cisa-task"><div><strong>${h(id)} · ${h(titleOf(allTopics().find(x=>x.id===id)||{title:id}))}</strong><small>Due ${h(fmtDate(date))}</small></div><div class="cisa-task-actions">${button('review-done','Reviewed','sm',`data-topic="${h(id)}"`)}${button('remove-review','Remove','sm',`data-topic="${h(id)}"`)}</div></div>`).join(''):'<div class="cisa-empty">No revisions due. Choose Add revision reminder on a weak topic.</div>'}</section>`}
function mocksUI(){return `<div class="cisa-grid three cisa-section">${[1,2,3].map(id=>{const latest=[...state.results].reverse().find(r=>r.mockId===id),draft=state.drafts[id];return `<section class="cisa-card"><div class="cisa-overline">Mock exam ${pad(id)}</div><h2>${h(['Foundation & Principles','Applied Audit Scenarios','Integrated Exam Readiness'][id-1])}</h2><p class="cisa-text cisa-muted">150 questions · 240 minutes · four choices · one best answer · 18 / 18 / 12 / 26 / 26 weighting.</p>${latest?badge('Latest score '+pct(latest.correct,latest.total)+'%','good'):'<span class="cisa-badge">Not completed</span>'}<div class="cisa-actions" style="margin-top:15px">${button('mock-start',draft?'Resume exam':'Start exam','primary',`data-mock="${id}"`)}${latest?button('mock-result','View results','',`data-mock="${id}"`):''}</div></section>`}).join('')}</div><section class="cisa-card cisa-section"><h2>Mock exam rules</h2><p class="cisa-text">The full-length simulator uses a countdown clock, answer navigation, flagged questions, saved draft answers, submission confirmation and post-exam explanations. The practice bank is original and independently written; it is <strong>not</strong> an official, leaked or licensed ISACA question set. Performance percentages do not represent ISACA scaled scores.</p><p class="cisa-text">For licensed official materials, see <a href="https://www.isaca.org/credentialing/cisa/cisa-practice-quiz" target="_blank" rel="noopener noreferrer">ISACA's practice quiz</a> and <a href="https://www.isaca.org/credentialing/cisa" target="_blank" rel="noopener noreferrer">CISA certification resources</a>.</p></section>`}
function examUI(){if(!examBank)return '<div class="cisa-empty">Loading the mock exam…</div>';const draft=state.drafts[examBank.id];if(!draft)return mocksUI();if(Date.now()>=draft.endAt){finishMock(examBank.id,true);tab='result';return resultUI(examBank.id)};const q=examBank.questions[examPage],answer=draft.answers[q.id],isFlag=draft.flags.includes(q.id),answered=Object.keys(draft.answers).length;return `<div class="cisa-exam"><div class="cisa-row wrap" style="margin-bottom:15px"><div><div class="cisa-overline">Practice exam ${examBank.id}</div><h2>${h(examBank.title)}</h2><div class="cisa-mini">Question ${examPage+1} / 150 · ${answered} answered · ${draft.flags.length} flagged</div></div><div class="cisa-actions"><span class="cisa-timer" data-time>${h(timeLeft(draft.endAt))}</span>${button('mock-submit','Submit exam','danger')}</div></div>${progress(pct(answered,150))}<div class="cisa-grid two cisa-section"><section class="cisa-card"><div class="cisa-row wrap"><span class="cisa-overline">Domain ${q.domain} · Topic ${h(q.topicId)}</span>${badge(q.level)}</div><p class="cisa-text" style="font-size:16px;font-weight:700;margin-top:14px">${h(q.question)}</p><div class="cisa-answers">${q.choices.map((choice,i)=>`<button type="button" class="cisa-answer ${answer===i?'selected':''}" data-action="choose" data-option="${i}" aria-pressed="${answer===i}"><b>${'ABCD'[i]}</b><span>${h(choice)}</span></button>`).join('')}</div><div class="cisa-actions">${button('mock-prev','← Previous','',''+(examPage===0?'disabled':''))}${button('flag',isFlag?'Unflag question':'Flag for review')}${button('mock-next','Next →','primary',examPage===149?'disabled':'')}</div></section><section class="cisa-card"><h3>Question navigator</h3><p class="cisa-mini">Filled: answered · gold outline: flagged</p><div class="cisa-number-grid">${examBank.questions.map((x,i)=>`<button type="button" data-action="mock-go" data-q="${i}" class="${i===examPage?'current':''} ${draft.answers[x.id]!==undefined?'answered':''} ${draft.flags.includes(x.id)?'flagged':''}" aria-label="Question ${i+1}">${i+1}</button>`).join('')}</div></section></div><div class="cisa-help">This is an exam simulation. Your draft and deadline are retained if you leave and return. Explanations appear only after submission.</div></div>`}
function timeLeft(end){const n=Math.max(0,Math.ceil((end-Date.now())/1000));return `${pad(Math.floor(n/3600))}:${pad(Math.floor(n%3600/60))}:${pad(n%60)}`}
function latestResult(id){return [...state.results].reverse().find(r=>r.mockId===id)}
function resultUI(id){const r=latestResult(id);if(!r)return mocksUI();const q=examBank?.id===id?examBank.questions:[],stats=r.stats||{};return `<div class="cisa-section"><section class="cisa-card"><div class="cisa-row wrap"><div><div class="cisa-overline">Practice exam ${id} · results</div><h2>${r.correct} / ${r.total} correct · ${pct(r.correct,r.total)}%</h2><p class="cisa-mini">Submitted ${h(fmtDate(r.date.slice(0,10)))} · ${Math.round(r.elapsed/60000)} minutes used · ${r.unanswered} unanswered</p></div>${button('nav','Back to mocks','','data-target="mocks"')}</div><div class="cisa-grid" style="margin-top:15px">${Object.entries(stats).map(([d,s])=>kpi('Domain '+d,`${pct(s.correct,s.total)}%`,`${s.correct}/${s.total} correct`)).join('')}</div><div class="cisa-help" style="margin-top:15px">Focus on your lowest-scoring domain and review incorrectly answered questions. This is a learning percentage; ISACA reports scaled scores, so it is not an official pass/fail determination.</div></section><section class="cisa-card cisa-section"><div class="cisa-row"><h2>Review questions & explanations</h2>${button('mock-reset','Retake this mock','','data-mock="'+id+'"')}</div>${q.length?`${(()=>{let qq=q[reviewQuestion],picked=r.answers[qq.id];return `<div class="cisa-row"><span class="cisa-mini">Question ${reviewQuestion+1} / 150 · ${h(qq.topicId)}</span>${badge(picked===qq.answer?'Correct':'Review',picked===qq.answer?'good':'warn')}</div><p class="cisa-text" style="font-weight:700">${h(qq.question)}</p><div class="cisa-answers">${qq.choices.map((ch,i)=>`<div class="cisa-answer ${i===qq.answer?'selected':''}"><b>${'ABCD'[i]}</b><div>${h(ch)}${i===qq.answer?' · Best answer':''}${i===picked&&i!==qq.answer?' · Your answer':''}</div></div>`).join('')}</div><div class="cisa-rationale"><b>Why this answer is best</b>${h(qq.explanation)}</div><div class="cisa-actions" style="margin-top:14px">${button('result-prev','← Previous','',''+(reviewQuestion===0?'disabled':''))}${button('result-next','Next →','primary',reviewQuestion===149?'disabled':'')}</div>`})()}`:'<div class="cisa-empty">Loading the separate answer bank for detailed review…</div>'}</section></div>`}
function analyticsUI(){const scores=domainScore(),t=timeline(),past=state.logs.slice(-14),top=weakTopics().filter(x=>x.accuracy!==null).slice(0,8);return `<div class="cisa-grid">${kpi('Study records',state.logs.length,'Logged sessions')}${kpi('Hours studied',(state.logs.reduce((s,x)=>s+(+x.minutes||0),0)/60).toFixed(1)+'h','Actual time')}${kpi('Topic coverage',totalComplete().percent+'%','Official syllabus')}${kpi('Mock attempts',state.results.length,'All sets combined')}</div><div class="cisa-grid two cisa-section"><section class="cisa-card"><h2>Study time trend</h2><p class="cisa-mini">Minutes per recent recorded session</p>${past.length?`<div class="cisa-chart">${past.map(l=>`<div title="${h(fmtDate(l.date))}: ${+l.minutes} minutes" style="height:${Math.max(6,Math.min(100,(+l.minutes||0)/180*100))}%"></div>`).join('')}</div>`:'<div class="cisa-empty">Log study sessions to see a trend.</div>'}</section><section class="cisa-card"><h2>Coverage and accuracy</h2>${scores.map(d=>`<div class="cisa-domain"><div class="cisa-row"><strong>D${d.domain} · ${h(d.name)}</strong><small>${d.coverage}% coverage · ${d.accuracy??'—'}${d.accuracy!==null?'%':' accuracy'}</small></div>${progress(d.coverage)}</div>`).join('')}</section></div><section class="cisa-card cisa-section"><h2>Practice attempt history</h2><div class="cisa-table-wrap"><table class="cisa-table"><thead><tr><th>Date</th><th>Mock</th><th>Correct</th><th>Percentage</th><th>Time</th></tr></thead><tbody>${state.results.length?state.results.slice().reverse().map(r=>`<tr><td>${h(fmtDate(r.date.slice(0,10)))}</td><td>${r.mockId}</td><td>${r.correct}/${r.total}</td><td>${pct(r.correct,r.total)}%</td><td>${Math.round(r.elapsed/60000)}m</td></tr>`).join(''):'<tr><td colspan="5">No submitted mocks yet.</td></tr>'}</tbody></table></div></section>`}
function notesUI(){return `<div class="cisa-grid two cisa-section"><section class="cisa-card"><h2>Personal knowledge notebook</h2><form data-form="notes"><label>Study topic<select name="id" data-action="note-switch">${allTopics().map(t=>`<option value="${h(t.id)}" ${focusedTopic===t.id?'selected':''}>${h(t.id)} · ${h(titleOf(t))}</option>`).join('')}</select></label><label style="margin:13px 0">Your notes<textarea name="note" maxlength="2500" placeholder="Summarize the concept, useful evidence, audit logic, and mistakes to avoid.">${h(state.notes[focusedTopic||allTopics()[0]?.id]||'')}</textarea></label><button class="cisa-btn primary" type="submit">Save note</button></form><div class="cisa-divider"></div>${Object.keys(state.notes).length?Object.entries(state.notes).map(([id,v])=>`<div class="cisa-list-item"><div class="cisa-row"><strong>${h(id)}</strong>${button('note-open','Edit','sm',`data-topic="${h(id)}"`)}</div><p class="cisa-mini">${h(v.slice(0,230))}</p></div>`).join(''):'<div class="cisa-empty">Your personal notes will appear here.</div>'}</section><section class="cisa-card"><h2>Progress export and backup</h2><p class="cisa-text cisa-muted">Your CISA data is stored alongside your authenticated JS Learning account progress through Firebase. You can also export a personal backup and dated study worksheet.</p><div class="cisa-actions">${button('export-json','Export JSON backup','primary')}${button('export-csv','Export study log CSV')}${button('export-plan','Export planner CSV')}</div><div class="cisa-divider"></div><form data-form="import"><label>Restore a previously exported CISA JSON file<input type="file" name="backup" accept=".json,application/json" required></label><button type="submit" class="cisa-btn" style="margin-top:12px">Import backup (replaces CISA records only)</button></form><div class="cisa-divider"></div><h3>Exam registration checklist</h3><label class="cisa-check"><input type="checkbox" data-action="registered" ${state.registration.registered?'checked':''}> Registered and paid through ISACA</label><label class="cisa-check" style="margin-top:10px"><input type="checkbox" data-action="booked" ${state.registration.booked?'checked':''}> Confirmed official PSI exam appointment</label><p class="cisa-mini" style="margin-top:12px">Planner dates are targets, not reservations. Confirm availability and exam eligibility directly with ISACA/PSI.</p></section></div>`}
function layout(){if(!root)return; if(tab==='exam'){root.innerHTML='<div class="cisa-hub">'+examUI()+'</div>';attach();return}if(tab==='result'){root.innerHTML='<div class="cisa-hub">'+resultUI(examBank?.id||1)+'</div>';attach();return}let content={overview,planner,syllabus:syllabusUI,recorder,revision:revisionsUI,mocks:mocksUI,analytics:analyticsUI,notes:notesUI};root.innerHTML='<div class="cisa-hub">'+header()+(content[tab]||overview)()+'</div>';attach();}
function attach(){if(timer){clearInterval(timer);timer=null}if(tab==='exam'){timer=setInterval(()=>{const draft=state.drafts[examBank?.id];if(!draft)return;if(Date.now()>=draft.endAt){clearInterval(timer);finishMock(examBank.id,true);tab='result';reviewQuestion=0;layout();return}const el=$('[data-time]');if(el)el.textContent=timeLeft(draft.endAt)},1000)}if(tab==='recorder'&&stopwatchStart)beginWatch()}
function navigate(t){if(timer){clearInterval(timer);timer=null}tab=t;editTopic=null;focusedTopic=null;layout();window.scrollTo({top:0,behavior:'instant'})}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function info(msg){alert(msg)}
async function loadBank(id){if(!examBank||examBank.id!==id)examBank=await fetchData(`./mock-exams/mock-0${id}.json`);return examBank}
function finishMock(id,auto=false){const draft=state.drafts[id];if(!draft||!examBank||examBank.id!==id)return;const data=examBank.questions,stats={},topicStats={},wrong=[];let correct=0;for(const q of data){const hit=draft.answers[q.id]===q.answer;if(hit)correct++;else wrong.push({id:q.id,topicId:q.topicId});stats[q.domain]??={total:0,correct:0};stats[q.domain].total++;if(hit)stats[q.domain].correct++;topicStats[q.topicId]??={total:0,correct:0};topicStats[q.topicId].total++;if(hit)topicStats[q.topicId].correct++;}const r={id:'r'+Date.now(),mockId:id,date:new Date().toISOString(),correct,total:data.length,unanswered:data.length-Object.keys(draft.answers).length,elapsed:Math.min(Date.now()-draft.startedAt,240*60000),stats,topicStats,wrong,answers:draft.answers,auto};state.results.push(r);state.results=state.results.slice(-30);delete state.drafts[id];state.activeMock=null;persist()}
function updateDraft(){persist();layout()}
function beginWatch(){if(stopWatch)clearInterval(stopWatch);stopWatch=setInterval(()=>{const el=$('#cisa-study-timer');if(el){const s=Math.floor((Date.now()-stopwatchStart+stopwatchElapsed)/1000);el.textContent=pad(Math.floor(s/60))+':'+pad(s%60)}},1000)}
function action(ev){const btn=ev.target.closest('[data-action]');if(!btn||!root.contains(btn))return;const a=btn.dataset.action,id=btn.dataset.topic,mode=btn.dataset.mock&&Number(btn.dataset.mock);if(btn.type==='checkbox')return;let previousScroll=window.scrollY;
 if(a==='nav'){navigate(btn.dataset.target);return}
 if(a==='mode-normal'||a==='mode-relaxed'){state.planMode=a.endsWith('normal')?'normal':'relaxed';weekIndex=0;persist();layout();return}
 if(a==='prev-week'||a==='next-week'||a==='today-week'){weekIndex=a==='prev-week'?weekIndex-1:a==='next-week'?weekIndex+1:clamp(Math.floor(dayDiff(getPlan().start,dateStr(new Date()))/7),0,99);layout();return}
 if(a==='reset-plan'){if(confirm('Restore the selected plan’s default dates and study hours? Completed work and notes will remain.')){state.plans[state.planMode]=structuredClone(templates[state.planMode]);persist();layout()}return}
 if(a==='edit-topic'||a==='new-topic'){editTopic=a==='new-topic'?'new':id;if(tab!=='planner'){tab='planner'}layout();$('#cisa-topic-detail')?.scrollIntoView();return}
 if(a==='cancel-edit'){editTopic=null;layout();return}
 if(a==='open-topic'){focusedTopic=id;tab=tab==='revision'?'revision':'syllabus';layout();$('#cisa-topic-detail')?.scrollIntoView({block:'start'});return}
 if(a==='close-topic'){focusedTopic=null;layout();return}
 if(a==='complete-toggle'){state.complete[id]=!state.complete[id];persist();layout();return}
 if(a==='move-up'||a==='move-down'){const arr=allTopics().map(x=>x.id),i=arr.indexOf(id),j=i+(a==='move-up'?-1:1);if(j>=0&&j<arr.length){[arr[i],arr[j]]=[arr[j],arr[i]];state.order=arr;persist();layout()}return}
 if(a==='delete-custom'){if(confirm('Delete this custom task?')){state.customTasks=state.customTasks.filter(x=>x.id!==id);state.order=state.order.filter(x=>x!==id);state.hidden=state.hidden.filter(x=>x!==id);delete state.complete[id];delete state.topicEdits[id];persist();layout()}return}
 if(a==='delete-log'){if(confirm('Delete this study record?')){state.logs=state.logs.filter(x=>x.id!==btn.dataset.id);persist();layout()}return}
 if(a==='schedule-review'||a==='review-done'){const count=state.revisionCounts[id]||0;const intervals=[1,3,7,14];if(a==='review-done')state.revisionCounts[id]=count+1;const date=dateAdd(dateStr(new Date()),a==='schedule-review'?1:intervals[Math.min(count,3)]);state.revisions[id]=date;persist();layout();return}
 if(a==='remove-review'){delete state.revisions[id];persist();layout();return}
 if(a==='catchup'){let ds=dateStr(new Date()),p=getPlan();if(ds<p.start)ds=p.start;for(let n=0;n<365;n++,ds=dateAdd(ds,1)){if((p.weeklyMinutes||[])[dayIdx(ds)]>0)break}if(ds>p.examDate){info('No remaining study day before your exam target. Edit the plan dates or weekly hours.');return}state.topicEdits[id]={...(state.topicEdits[id]||{}),date:ds};persist();layout();return}
 if(a==='timer-start'){if(!stopwatchStart){stopwatchStart=Date.now()}beginWatch();return}
 if(a==='timer-stop'){if(stopwatchStart){stopwatchElapsed+=Date.now()-stopwatchStart;stopwatchStart=null}clearInterval(stopWatch);const el=$('#cisa-duration');if(el)el.value=Math.max(1,Math.ceil(stopwatchElapsed/60000));return}
 if(a==='export-json'){download('cisa-backup-'+dateStr(new Date())+'.json',JSON.stringify({kind:'jslearning-cisa-v1',data:state},null,2),'application/json');return}
 if(a==='export-csv'){download('cisa-study-records.csv',csv([['Date','Domain','Topic','Minutes','Questions','Correct','Confidence','Notes'],...state.logs.map(x=>[x.date,x.domain,x.topicId,x.minutes,x.questions,x.correct,x.confidence,x.notes])]),'text/csv');return}
 if(a==='export-plan'){
   const t=timeline();
   const rows=[['Date','Task','Domain','Minutes','Complete']];
   for(const d of t.days){for(const x of t.byday[d]){
     rows.push([d,x.topic?titleOf(x.topic):x.mock?'Mock '+x.mock:'Target CISA exam',x.topic?x.topic.domain:'',x.minutes,x.topic?!!state.complete[x.topic.id]:'']);
   }}
   download('cisa-planner-'+state.planMode+'.csv',csv(rows),'text/csv');return;
 }
 if(a==='note-open'){focusedTopic=id;tab='notes';layout();return}
 if(a==='mock-start'){if(!state.drafts[mode]){if(!confirm('Start a 150-question, four-hour practice exam? Your timer will continue if you navigate away.'))return;state.drafts[mode]={startedAt:Date.now(),endAt:Date.now()+240*60000,answers:{},flags:[]};persist()}tab='exam';examPage=0;loadBank(mode).then(()=>layout()).catch(e=>fail(e.message));layout();return}
 if(a==='mock-result'){tab='result';reviewQuestion=0;loadBank(mode).then(()=>layout()).catch(e=>fail(e.message));layout();return}
 if(a==='choose'){const d=state.drafts[examBank.id],q=examBank.questions[examPage];d.answers[q.id]=Number(btn.dataset.option);updateDraft();return}
 if(a==='flag'){const d=state.drafts[examBank.id],q=examBank.questions[examPage];d.flags.includes(q.id)?d.flags=d.flags.filter(x=>x!==q.id):d.flags.push(q.id);updateDraft();return}
 if(a==='mock-go'||a==='mock-prev'||a==='mock-next'){examPage=a==='mock-go'?Number(btn.dataset.q):clamp(examPage+(a==='mock-prev'?-1:1),0,149);layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='mock-submit'){const d=state.drafts[examBank.id];const remaining=150-Object.keys(d.answers).length;if(confirm(`Submit this mock examination now? ${remaining} questions are unanswered. You will then see the score and explanations.`)){finishMock(examBank.id);tab='result';reviewQuestion=0;layout()}return}
 if(a==='result-prev'||a==='result-next'){reviewQuestion=clamp(reviewQuestion+(a==='result-prev'?-1:1),0,149);layout();return}
 if(a==='mock-reset'){if(confirm('Start a fresh attempt? Previous submitted results are preserved.')){delete state.drafts[mode];persist();tab='mocks';layout()}return}
 }
function changes(e){const el=e.target;if(!el.dataset.action)return;const a=el.dataset.action,id=el.dataset.topic;if(a==='note-switch'){focusedTopic=el.value;layout();return}if(a==='complete'){state.complete[id]=el.checked;persist();layout();return}if(a==='include'){state.hidden=el.checked?state.hidden.filter(x=>x!==id):[...new Set([...state.hidden,id])];persist();layout();return}if(a==='registered'||a==='booked'){state.registration[a]=el.checked;persist();return}}
async function submit(e){const f=e.target;if(!f.dataset.form)return;e.preventDefault();const v=Object.fromEntries(new FormData(f));const n=f.dataset.form;
 if(n==='plan'){if(v.start>=v.examDate){info('The target exam date must be later than the start date.');return}if(v.examDate>v.deadline){info('Target exam date must be on or before your deadline.');return}if(dayDiff(v.start,v.examDate)>729){info('Use a study period shorter than two years.');return}const p=getPlan();Object.assign(p,{start:v.start,examDate:v.examDate,deadline:v.deadline,title:v.title.slice(0,90),reviewDays:clamp(+v.reviewDays||10,3,40),weeklyMinutes:WD.map((_,i)=>clamp(+v['wd'+i]||0,0,600))});if(p.weeklyMinutes.every(x=>!x)){info('Set study time on at least one day per week.');return}state.plans[state.planMode]=p;weekIndex=0;persist();layout();return}
 if(n==='topic'){const id=v.id;if(!v.title.trim()){info('Enter a topic title.');return}if(v.date&&(v.date<getPlan().start||v.date>getPlan().examDate)){info('Preferred date must be between the plan start and target exam date.');return}if(id==='new'){let newId='P'+Date.now().toString(36);state.customTasks.push({id:newId,title:v.title.trim(),domain:clamp(+v.domain,1,5),section:'Personal study',minutes:clamp(+v.minutes,15,300),custom:true});state.topicEdits[newId]={date:v.date||'',notes:v.notes||'',title:v.title.trim(),minutes:clamp(+v.minutes,15,300)};}else{state.topicEdits[id]={title:v.title.trim(),minutes:clamp(+v.minutes,15,300),date:v.date||'',notes:v.notes||''};if(state.customTasks.some(x=>x.id===id)){state.customTasks.find(x=>x.id===id).domain=clamp(+v.domain,1,5)}}editTopic=null;persist();layout();return}
 if(n==='log'){if(+v.correct>+v.questions){info('Correct answers cannot exceed questions attempted.');return}if(!v.date||!+v.minutes){info('Date and study duration are required.');return}state.logs.push({id:'log'+Date.now(),date:v.date,domain:+v.domain,topicId:v.topicId||'',minutes:clamp(+v.minutes,1,1440),questions:clamp(+v.questions||0,0,1000),correct:clamp(+v.correct||0,0,1000),confidence:+v.confidence,notes:(v.notes||'').slice(0,1000)});state.logs=state.logs.slice(-200);stopwatchStart=null;stopwatchElapsed=0;clearInterval(stopWatch);persist();layout();return}
 if(n==='notes'){state.notes[v.id]=(v.note||'').slice(0,2500);focusedTopic=v.id;persist();layout();return}
 if(n==='import'){const file=f.elements.backup.files?.[0];if(!file)return;if(file.size>2_000_000){info('Backup is too large (maximum 2 MB).');return}try{const obj=JSON.parse(await file.text());if(obj.kind!=='jslearning-cisa-v1'||!obj.data||typeof obj.data!=='object')throw Error('Not a JS Learning CISA backup');if(!confirm('Replace this account’s existing CISA progress with the imported backup?'))return;state=Object.assign(defaultState(),obj.data);ensureImported();persist();layout()}catch(err){info('Unable to import: '+err.message)}return}
}
function ensureImported(){state.plans=state.plans||{};state.complete=state.complete||{};state.topicEdits=state.topicEdits||{};state.customTasks=Array.isArray(state.customTasks)?state.customTasks:[];state.logs=Array.isArray(state.logs)?state.logs:[];state.results=Array.isArray(state.results)?state.results:[];state.order=Array.isArray(state.order)?state.order:[];state.hidden=Array.isArray(state.hidden)?state.hidden:[];state.notes=state.notes||{};state.revisions=state.revisions||{};state.drafts=state.drafts||{};state.registration=state.registration||{registered:false,booked:false};state.revisionCounts=state.revisionCounts||{};if(!state.plans.normal)state.plans.normal=structuredClone(templates.normal);if(!state.plans.relaxed)state.plans.relaxed=structuredClone(templates.relaxed);if(!['normal','relaxed'].includes(state.planMode))state.planMode='normal'}
function fail(message){if(root)root.innerHTML=`<div class="cisa-hub"><div class="cisa-error"><b>Unable to load the CISA module.</b><p>${h(message)}</p><p>Upload <code>cisa/</code> as a folder alongside <code>index.html</code>, including its JS, CSS and JSON files.</p></div></div>`}
export async function mount({root:target,read,write}){root=target;readParent=read;writeParent=write;root.innerHTML='<div class="cisa-hub"><div class="cisa-card">Loading CISA Academy, planner and syllabus…</div></div>';try{if(!syllabus){[syllabus,templates.normal,templates.relaxed]=await Promise.all([fetchData('./data/syllabus.json'),fetchData('./data/normal-plan.json'),fetchData('./data/relaxed-plan.json')])}ensureState();weekIndex=clamp(Math.floor(dayDiff(getPlan().start,dateStr(new Date()))/7),0,99);root.onclick=action;root.onchange=changes;root.onsubmit=submit;layout()}catch(e){console.error(e);fail(e.message)}}
